<?php
session_start();
require_once __DIR__ . '/../includes/role_helpers.php';
requireAnyRole(['user']);
require_once __DIR__ . '/../config/database.php';

$userId = (int)$_SESSION['user_id'];
$stmt = $conn->prepare("SELECT id, transaction_number, total_amount, sale_date FROM sales WHERE user_id = ? AND transaction_number LIKE 'ORDER-%' ORDER BY sale_date DESC, id DESC");
$stmt->bind_param('i', $userId);
$stmt->execute();
$orders = $stmt->get_result();
?>
